from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'evs','family-and-friends','Family and Friends',
 ('Bela\'s family and Shiru the dog','Bela lives with her parents, her brothers Banku and Bishu, her grandparents Dadiji and Dadaji and a dog named Shiru. In the evenings they play hide and seek in the garden, and on rainy days they sit in a small shelter, eat pakodas and sing rain songs. Bela tells us how families and friends play, work and care for each other.'),
 [('Playing together',['Bela and her brothers play chhupan-chhupai, which is hide and seek, in the open space outside their house. Games bring the family close.','They play peek-a-boo with little Bishu, where someone hides and suddenly shows their face and says peek-a-boo.','Their grandfather Dadaji teaches the children games he played with his friends when he was a child. Elders know many old games we can learn.','Relatives, friends and neighbours visit their garden. They sit, talk, share jokes and laugh together.']),
  ('Singing and sharing',['On rainy days the family sits in a small shelter in the garden, plays antakshari and snakes and ladders, and eats hot pakodas.','Dadiji sings songs about the rain and teaches the children, so they join in. Songs and stories pass from grandparents to children.','Shiru, the dog, is part of Bela\'s family. The children never hurt him, and they share food with him. We should be kind and caring to animals, and we should not tease or hurt them.']),
  ('Types of families',['Families can be big or small. Some have parents and children, some also have grandparents and other relatives.','A family has mothers, fathers, grandparents, brothers, sisters and other elders. They love each other and take care of each other.','Even pets such as cows, buffaloes, dogs, parrots, cats and goats can be a part of a family when we love and look after them.','We call our relatives by names that show how they are related to us, such as mausi for mother\'s sister, dadi for father\'s mother or dada for father\'s father.']),
  ('Helping each other',['In Bela\'s house everyone helps. Her parents share the housework, from cooking and cleaning to shopping.','Dadiji oils and braids Bela\'s hair before school and hums a song. Dadaji loves gardening, and Bela helps him in the garden.','Banku helps by cleaning and chopping vegetables. Each person helps in a way that suits them.','Kusum Mausi and her daughter Munni are close friends who live nearby. Kusum Mausi cooks sweets for festivals, and Munni makes rangoli with colours from dried flowers.','We learn many things from family members and neighbours, such as songs, games, cooking and making rangoli.'])],
 [('Bela\'s family has grandparents, parents, two brothers and a dog. Is it a big family or a small family?',[('Count the members: Dadiji, Dadaji, father, mother, Banku, Bela, Bishu and Shiru.','Count everyone, including the pet.'),('There are many members living together.','A big family has many members.'),('So it is a big family.','The number of members decides big or small, and both are good.')]),
  ('Why should we not tease or hurt animals like Shiru?',[('Animals feel pain and fear like us.','They are living beings.'),('Shiru shares our home and gives us love and guards the house.','Pets are part of the family.'),('So we should care for animals and share our food and water.','Kindness makes animals feel safe.')])],
 ('Tell about your own family and how its members help each other.',['Name the family members','Say who they are to you','Tell how they help each other','Mention one thing you learnt from them'],['A family has only a mother and father','Pets are not part of a family']),
 ['Families can be big or small, and they love and care for each other.','Family members help each other with work and play.','We learn songs, games and skills from elders, friends and neighbours.','Animals can be part of a family and we should be kind to them.','Friends and neighbours support us too.'],
 [M('1',1,'Who is Shiru?','The family\'s dog',[('Bela\'s brother','Shiru is a pet'),('A neighbour','Shiru lives with the family')],'Shiru is a dog and part of the family.'),
  M('2',1,'Which game do Bela and her brothers play outside?','Hide and seek',[('Cricket only','The story says hide and seek'),('Chess','The story names chhupan-chhupai')],'Chhupan-chhupai is hide and seek.'),
  M('3',1,'What does Dadiji do for Bela before school?','Oils and braids her hair',[('Cooks pakodas','She does that on rainy days'),('Teaches maths','She helps with hair')],'Dadiji oils and braids Bela\'s hair.'),
  M('4',1,'Who is Munni?','Bela\'s close friend',[('Bela\'s sister','Munni is a friend'),('A teacher','Munni is a friend')],'Munni and her mother live near Bela\'s house.'),
  F('5',2,'A family can have animals as members.',True,'Cows, dogs, cats and parrots can be part of a family.'),
  F('6',2,'All families have the same number of members.',False,'Families can be big or small.'),
  M('7',2,'What do we call mother\'s sister?','Mausi',[('Dadi','Dadi is father\'s mother'),('Chacha','Chacha is father\'s brother')],'Mausi is mother\'s sister.'),
  M('8',2,'What do the family do on rainy days?','Sit in a shelter, play games and eat pakodas',[('Stay asleep','They play and sing'),('Go to the market','They stay in the garden shelter')],'They sing and eat hot pakodas.'),
  S('9',2,'What does Munni make using colours from dried flowers?',['rangoli','Rangoli'],'Munni makes rangoli.'),
  M('10',2,'Why should we be kind to animals?','They are living beings who feel pain and fear',[('They are only toys','Animals are living'),('They cannot feel','They feel pain')],'Kindness makes them feel safe.'),
  M('11',3,'How do families show care?','By helping and sharing',[('By staying apart','Care means helping'),('By ignoring each other','Care means looking after each other')],'Helping each other shows care.'),
  F('12',3,'We can learn games and songs from our grandparents.',True,'Elders pass on games and songs.')],
 keep=['family','neighbour'])
